local function InitializeJunkie()
    local success, junkie = pcall(function()
        return loadstring(game:HttpGet("https://jnkie.com/sdk/library.lua"))()
    end)
    
    if success and junkie then
        junkie.service = "sharp-services-linkvertise"
        junkie.identifier = "1007877"
        junkie.provider = "sharp-provider-linkvertise"
        return junkie
    end
    return nil
end

local function GenerateHWID()
    local platform = tostring(UserInputService:GetPlatform())
    local userId = tostring(LocalPlayer.UserId)
    local gameId = tostring(game.GameId)
    local hardwareId = platform .. "_" .. userId .. "_" .. gameId
    
    local success, externalHWID = pcall(function()
        if gethwid then
            return gethwid()
        end
        return ""
    end)
    
    if success and externalHWID ~= "" then
        hardwareId = externalHWID .. "_" .. hardwareId
    end
    
    local hash = ""
    for i = 1, #hardwareId do
        local byte = string.byte(hardwareId, i)
        local char = string.char(((byte + i) % 26) + 65)
        hash = hash .. char
    end
    
    return hash .. "_" .. string.sub(tostring(math.floor(os.time()/3600)), -4)
end

local function SavePersistentData()
    if not IsSupportedExploit then 
        local data = {
            lastCopyTime = PersistentData.lastCopyTime,
            cooldownEndTime = PersistentData.cooldownEndTime,
            timestamp = os.time()
        }
        return true
    end
    
    local data = {
        lastCopyTime = PersistentData.lastCopyTime,
        verifiedKey = PersistentData.verifiedKey,
        hwid = PersistentData.hwid,
        cooldownEndTime = PersistentData.cooldownEndTime,
        timestamp = os.time()
    }
    
    local success, json = pcall(function()
        return HttpService:JSONEncode(data)
    end)
    
    if success and json then
        local ok = pcall(function()
            writefile("v3neno_hub_data.json", json)
        end)
        return ok
    end
    return false
end

local function LoadPersistentData()
    if not IsSupportedExploit then return false end
    
    local currentHWID = GenerateHWID()
    
    if isfile("v3neno_hub_data.json") then
        local success, content = pcall(function()
            return readfile("v3neno_hub_data.json")
        end)
        if success and content then
            local ok, data = pcall(function()
                return HttpService:JSONDecode(content)
            end)
            if ok and data then
                if data.hwid == currentHWID then
                    PersistentData.lastCopyTime = data.lastCopyTime or 0
                    PersistentData.verifiedKey = data.verifiedKey
                    PersistentData.hwid = data.hwid
                    PersistentData.cooldownEndTime = data.cooldownEndTime or 0
                    
                    if PersistentData.cooldownEndTime > 0 and os.time() >= PersistentData.cooldownEndTime then
                        PersistentData.cooldownEndTime = 0
                        SavePersistentData()
                    end
                    
                    return true
                else
                    PersistentData.lastCopyTime = 0
                    PersistentData.verifiedKey = nil
                    PersistentData.hwid = currentHWID
                    PersistentData.cooldownEndTime = 0
                    SavePersistentData()
                end
            end
        end
    else
        PersistentData.hwid = currentHWID
        SavePersistentData()
    end
    return false
end

local function FormatTime(seconds)
    local minutes = math.floor(seconds / 60)
    local secs = seconds % 60
    return string.format("%02d:%02d", minutes, secs)
end

local function MakeDraggable(topbarobject, object)
    local Dragging = nil
    local DragInput = nil
    local DragStart = nil
    local StartPos = nil
    
    local function Update(input)
        local Delta = input.Position - DragStart
        local Position = UDim2.new(StartPos.X.Scale, StartPos.X.Offset + Delta.X, StartPos.Y.Scale, StartPos.Y.Offset + Delta.Y)
        object.Position = Position
    end
    
    topbarobject.InputBegan:Connect(function(input)
        if input.UserInputType == Enum.UserInputType.MouseButton1 or input.UserInputType == Enum.UserInputType.Touch then
            Dragging = true
            DragStart = input.Position
            StartPos = object.Position
            input.Changed:Connect(function()
                if input.UserInputState == Enum.UserInputState.End then
                    Dragging = false
                end
            end)
        end
    end)
    
    topbarobject.InputChanged:Connect(function(input)
        if input.UserInputType == Enum.UserInputType.MouseMovement or input.UserInputType == Enum.UserInputType.Touch then
            DragInput = input
        end
    end)
    
    UserInputService.InputChanged:Connect(function(input)
        if input == DragInput and Dragging then
            Update(input)
        end
    end)
end

local function ValidateKey(key)
    key = string.gsub(key, "%s+", "")
    
    if #key < 5 then
        return false, "Key too short"
    end
    
    if JunkieAPI then
        local result = JunkieAPI.check_key(key)
        if result and result.valid then
            return true, "Key verified via Junkie"
        elseif result and result.message then
            return false, result.message
        end
    end
    
    if #key < 16 then
        return false, "Key too short"
    end
    
    if not string.match(key, "^[A-Z0-9][A-Z0-9%-_]+[A-Z0-9]$") then
        return false, "Invalid key format"
    end
    
    return false, "Verification service unavailable"
end

