    end)
    
    GetKeyButton.MouseButton1Click:Connect(function()
        if copyCooldownActive then
            UpdateStatus("Please wait for cooldown", Color3.fromRGB(255, 165, 0), 2)
            return
        end
        
        if JunkieAPI then
            local link = JunkieAPI.get_key_link()
            if link then
                if setclipboard then
                    setclipboard(link)
                    UpdateStatus("Key link copied!", Colors.Accent, 3)
                else
                    UpdateStatus("Get key: " .. link, Colors.Accent, 5)
                end
            else
                UpdateStatus("Failed to get link", Colors.Danger, 3)
            end
        else
            UpdateStatus("Junkie system unavailable", Colors.Danger, 3)
        end
        
        copyCooldownActive = true
        PersistentData.lastCopyTime = os.time()
        PersistentData.cooldownEndTime = PersistentData.lastCopyTime + KeySystem.CopyCooldown
        SavePersistentData()
        
        GetKeyButton.Text = "WAIT"
        GetKeyButton.BackgroundColor3 = Color3.fromRGB(35, 35, 35)
        
        local timerConnection
        local function UpdateTimer()
            local remaining = math.max(0, PersistentData.cooldownEndTime - os.time())
            
            if remaining > 0 then
                GetKeyButton.Text = FormatTime(remaining)
                return true
            else
                copyCooldownActive = false
                GetKeyButton.Text = "GET KEY"
                GetKeyButton.BackgroundColor3 = Color3.fromRGB(0, 100, 255)
                PersistentData.cooldownEndTime = 0
                SavePersistentData()
                if timerConnection then
                    timerConnection:Disconnect()
                end
                return false
            end
        end
        
        timerConnection = RunService.Heartbeat:Connect(function()
            if not UpdateTimer() then
                timerConnection:Disconnect()
            end
        end)
    end)
    
    VerifyButton.MouseButton1Click:Connect(function()
        local key = KeyInput.Text
        
        if #key < 5 then
            UpdateStatus("Please enter a valid key", Colors.Danger, 2)
            return
        end
        
        local isValid, message = ValidateKey(key)
        
        if isValid then
            PersistentData.verifiedKey = key
            SavePersistentData()
            
            UpdateStatus("✓ Key verified successfully!", Colors.Accent, 0)
            
            TweenService:Create(IconLabel, SmoothInfo, {
                TextSize = 32,
                Rotation = 360
            }):Play()
            
            task.wait(0.5)
            
            TweenService:Create(IconLabel, SmoothInfo, {
                TextSize = 26,
                Rotation = 0
            }):Play()
            
            task.wait(1)
            KeyPanel:Destroy()
            Library:CreateWindow()
        else
            UpdateStatus(message or "Invalid key", Colors.Danger, 3)
        end
    end)
    
    KeyInput.FocusLost:Connect(function(enterPressed)
        if enterPressed then
            task.wait(0.1)
            VerifyButton.MouseButton1Click:Fire()
        end
    end)
    
    return KeyPanel
end

local function ToggleESPName()
    if ESPNameActive then
        ESPNameActive = false
        if ESPNameCleanup then
            ESPNameCleanup()
            ESPNameCleanup = nil
        end
        print("ESP NAME DESATIVADO")
        return false
    else
        ESPNameActive = true
        
        local Players = game:GetService("Players")
        local RunService = game:GetService("RunService")
        local LocalPlayer = Players.LocalPlayer
        local CoreGui = game:GetService("CoreGui")
        
        local activeNameTags = {}
        local characterConnections = {}
        local isCleaning = false
        
        local function cleanAll()
            if isCleaning then return end
            isCleaning = true
            
            for character, bill in pairs(activeNameTags) do
                if bill and bill.Parent then
                    bill:Destroy()
                end
                if characterConnections[character] then
                    for _, conn in pairs(characterConnections[character]) do
                        pcall(function() conn:Disconnect() end)
                    end
                end
            end
            
            table.clear(activeNameTags)
            table.clear(characterConnections)
            
            isCleaning = false
        end
        
        local function getTeamColor(targetPlayer)
            if not targetPlayer or targetPlayer == LocalPlayer then return nil end
            
            local localTeam = LocalPlayer.Team
            local targetTeam = targetPlayer.Team
            
            if not localTeam or not targetTeam then
                return Color3.fromRGB(255, 255, 0)
            end
            
            if localTeam == targetTeam then
                return Color3.fromRGB(0, 150, 255)
            else
                return Color3.fromRGB(255, 0, 0)
            end
        end
        
        local function isValidCharacter(character)
            if not character or not character:IsA("Model") then return false end
            
            local player = Players:GetPlayerFromCharacter(character)
            if not player then return false end
            if player == LocalPlayer then return false end
            
            local humanoid = character:FindFirstChildOfClass("Humanoid")
            if not humanoid or humanoid.Health <= 0 then return false end
            
            local head = character:FindFirstChild("Head")
            if not head then return false end
            
            return true
        end
        
        local function removeNameTag(character)
            if not character then return end
            
            if activeNameTags[character] then
                activeNameTags[character]:Destroy()
                activeNameTags[character] = nil
            end
            
            if characterConnections[character] then
                for _, conn in pairs(characterConnections[character]) do
                    pcall(function() conn:Disconnect() end)
                end
                characterConnections[character] = nil
            end
        end
        
        local function setupCharacter(character)
            if not isValidCharacter(character) then return end
            
            removeNameTag(character)
            
            local head = character:WaitForChild("Head", 2)
            if not head then return end
            
            local bill = Instance.new("BillboardGui")
            bill.Name = "V3ENO_Name"
            bill.Adornee = head
            bill.Size = UDim2.new(0, 200, 0, 40)
            bill.StudsOffset = Vector3.new(0, 3.5, 0)
            bill.AlwaysOnTop = true
            bill.MaxDistance = 500
            bill.Enabled = true
            
            local label = Instance.new("TextLabel")
            label.Parent = bill
            label.BackgroundTransparency = 1
            label.Size = UDim2.new(1, 0, 1, 0)
            label.Position = UDim2.new(0, 0, 0, 0)
            label.TextSize = 16
            label.Font = Enum.Font.GothamBold
            label.TextStrokeTransparency = 0.5
            label.TextStrokeColor3 = Color3.new(0, 0, 0)
            
            bill.Parent = CoreGui
            activeNameTags[character] = bill
            
            local player = Players:GetPlayerFromCharacter(character)
            local connections = {}
            
            local function update()
                if not bill or bill.Parent ~= CoreGui then return end
                
                local currentPlayer = Players:GetPlayerFromCharacter(character)
                if currentPlayer and character:FindFirstChild("Head") then
                    label.Text = player.Name
                    local color = getTeamColor(currentPlayer)
                    if color then
                        label.TextColor3 = color
                    else
                        removeNameTag(character)
                    end
                else
                    removeNameTag(character)
                end
            end
            
            if player then
                table.insert(connections, player:GetPropertyChangedSignal("Team"):Connect(update))
                table.insert(connections, LocalPlayer:GetPropertyChangedSignal("Team"):Connect(update))
            end
            
            local humanoid = character:FindFirstChildOfClass("Humanoid")
            if humanoid then
                table.insert(connections, humanoid.Died:Connect(function()
                    removeNameTag(character)
                end))
            end
            
            table.insert(connections, character.AncestryChanged:Connect(function()
                if not character or not character.Parent then
                    removeNameTag(character)
                end
            end))
            
            characterConnections[character] = connections
            update()
        end
        
        local function checkExistingCharacters()
            for _, player in pairs(Players:GetPlayers()) do
                if player ~= LocalPlayer and player.Character then
                    setupCharacter(player.Character)
                end
            end
        end
        
        local function playerAdded(player)
            local charAddedConn = player.CharacterAdded:Connect(function(character)
                task.wait(1)
                if ESPNameActive then
                    setupCharacter(character)
                end
            end)
            if player.Character and ESPNameActive then
                task.spawn(setupCharacter, player.Character)
            end
            
            return charAddedConn
        end
        
        local playersConn = Players.PlayerAdded:Connect(playerAdded)
        local playerRemovedConn = Players.PlayerRemoving:Connect(function(player)
            if player.Character then
                removeNameTag(player.Character)
            end
        end)
        
        local playerCharAddedConn = LocalPlayer.CharacterAdded:Connect(function()
            task.wait(1)
            if ESPNameActive then
                cleanAll()
                checkExistingCharacters()
            end
        end)
        
        local heartbeatConn = RunService.Heartbeat:Connect(function()
            if not ESPNameActive then return end
            for character, bill in pairs(activeNameTags) do
                if not isValidCharacter(character) then
                    removeNameTag(character)
                end
            end
        end)
        
        checkExistingCharacters()
        
        local playerConnections = {}
        for _, player in pairs(Players:GetPlayers()) do
            if player ~= LocalPlayer then
                playerConnections[player] = playerAdded(player)
            end
        end
        
        local function cleanup()
            playersConn:Disconnect()
            playerRemovedConn:Disconnect()
            playerCharAddedConn:Disconnect()
            heartbeatConn:Disconnect()
            
            for _, conn in pairs(playerConnections) do
                conn:Disconnect()
            end
            
            cleanAll()
            ESPNameActive = false
        end
        
        ESPNameCleanup = cleanup
        print("ESP NAME ATIVADO")
        return true
    end
end

local function ToggleESPLine()
    if ESPLineActive then
        ESPLineActive = false
        if ESPLineCleanup then
            ESPLineCleanup()
            ESPLineCleanup = nil
        end
        print("ESP LINE DESATIVADO")
        return false
    else
        ESPLineActive = true
        
        local Players = game:GetService("Players")
        local RunService = game:GetService("RunService")
        local Camera = workspace.CurrentCamera
        local LocalPlayer = Players.LocalPlayer
        
        local activeTracers = {}
        local characterConnections = {}
        local tracerConnections = {}
        local isCleaning = false
        
        local function cleanAll()
            if isCleaning then return end
            isCleaning = true
            
            for character, line in pairs(activeTracers) do
                if line then
                    pcall(function() line:Remove() end)
                end
                if tracerConnections[character] then
                    pcall(function() tracerConnections[character]:Disconnect() end)
                end
                if characterConnections[character] then
                    for _, conn in pairs(characterConnections[character]) do
                        pcall(function() conn:Disconnect() end)
                    end
                end
            end
            
            table.clear(activeTracers)
            table.clear(characterConnections)
            table.clear(tracerConnections)
            
            isCleaning = false
        end
        
        local function getTeamColor(targetPlayer)
            if not targetPlayer or targetPlayer == LocalPlayer then return nil end
            
            local localTeam = LocalPlayer.Team
            local targetTeam = targetPlayer.Team
            
            if not localTeam or not targetTeam then
                return Color3.fromRGB(255, 255, 0)
            end
            
            if localTeam == targetTeam then
                return Color3.fromRGB(0, 150, 255)
            else
                return Color3.fromRGB(255, 0, 0)
            end
        end
        
        local function isValidCharacter(character)
            if not character or not character:IsA("Model") then return false end
            
            local player = Players:GetPlayerFromCharacter(character)
            if not player then return false end
            if player == LocalPlayer then return false end
            
            local humanoid = character:FindFirstChildOfClass("Humanoid")
            if not humanoid or humanoid.Health <= 0 then return false end
            
            local hrp = character:FindFirstChild("HumanoidRootPart")
            if not hrp then return false end
            
            return true
        end
        
        local function removeTracer(character)
            if not character then return end
            
            if activeTracers[character] then
                pcall(function() activeTracers[character]:Remove() end)
                activeTracers[character] = nil
            end
            
            if tracerConnections[character] then
                pcall(function() tracerConnections[character]:Disconnect() end)
                tracerConnections[character] = nil
            end
            
            if characterConnections[character] then
                for _, conn in pairs(characterConnections[character]) do
                    pcall(function() conn:Disconnect() end)
                end
                characterConnections[character] = nil
            end
        end
        
        local function setupCharacter(character)
            if not isValidCharacter(character) then return end
            
            removeTracer(character)
            
            local line = Drawing.new("Line")
            line.Visible = false
            line.Thickness = 1.5
            line.Transparency = 0.8
            
            local player = Players:GetPlayerFromCharacter(character)
            local color = getTeamColor(player)
            if not color then
                line:Remove()
                return
            end
            
            line.Color = color
            activeTracers[character] = line
            
            local connections = {}
            
            if player then
                table.insert(connections, player:GetPropertyChangedSignal("Team"):Connect(function()
                    if activeTracers[character] then
                        local newColor = getTeamColor(player)
                        if newColor then
                            activeTracers[character].Color = newColor
                        end
                    end
                end))
                table.insert(connections, LocalPlayer:GetPropertyChangedSignal("Team"):Connect(function()
                    if activeTracers[character] then
                        local newColor = getTeamColor(player)
                        if newColor then
                            activeTracers[character].Color = newColor
                        end
                    end
                end))
            end
            
            local humanoid = character:FindFirstChildOfClass("Humanoid")
            if humanoid then
                table.insert(connections, humanoid.Died:Connect(function()
                    removeTracer(character)
                end))
            end
            
            table.insert(connections, character.AncestryChanged:Connect(function()
                if not character or not character.Parent then
                    removeTracer(character)
                end
            end))
            
            characterConnections[character] = connections
            
            local connection = RunService.RenderStepped:Connect(function()
                if not ESPLineActive or not line or not character or not character.Parent then
                    if not ESPLineActive then
                        removeTracer(character)
                    end
                    return
                end
                
                local humanoidRootPart = character:FindFirstChild("HumanoidRootPart")
                if not humanoidRootPart then
                    line.Visible = false
                    return
                end
                
                local hrpPos, onScreen = Camera:WorldToViewportPoint(humanoidRootPart.Position)
                
                if onScreen then
                    line.From = Vector2.new(Camera.ViewportSize.X / 2, Camera.ViewportSize.Y)
                    line.To = Vector2.new(hrpPos.X, hrpPos.Y)
                    line.Visible = true
                else
                    line.Visible = false
                end
            end)
            
            tracerConnections[character] = connection
        end
        
        local function checkExistingCharacters()
            for _, player in pairs(Players:GetPlayers()) do
                if player ~= LocalPlayer and player.Character then
                    setupCharacter(player.Character)
                end
            end
        end
        
        local function playerAdded(player)
            local charAddedConn = player.CharacterAdded:Connect(function(character)
                task.wait(1)
                if ESPLineActive then
                    setupCharacter(character)
                end
            end)
            if player.Character and ESPLineActive then
                task.spawn(setupCharacter, player.Character)
            end
            
            return charAddedConn
        end
        
        local playersConn = Players.PlayerAdded:Connect(playerAdded)
        local playerRemovedConn = Players.PlayerRemoving:Connect(function(player)
            if player.Character then
                removeTracer(player.Character)
            end
        end)
        
        local playerCharAddedConn = LocalPlayer.CharacterAdded:Connect(function()
            task.wait(1)
            if ESPLineActive then
                cleanAll()
                checkExistingCharacters()
            end
        end)
        
        local heartbeatConn = RunService.Heartbeat:Connect(function()
            if not ESPLineActive then return end
            for character, line in pairs(activeTracers) do
                if not isValidCharacter(character) then
                    removeTracer(character)
                end
            end
        end)
        
        checkExistingCharacters()
        
        local playerConnections = {}
        for _, player in pairs(Players:GetPlayers()) do
            if player ~= LocalPlayer then
                playerConnections[player] = playerAdded(player)
            end
        end
        
        local function cleanup()
            playersConn:Disconnect()
            playerRemovedConn:Disconnect()
            playerCharAddedConn:Disconnect()
            heartbeatConn:Disconnect()
            
            for _, conn in pairs(playerConnections) do
                conn:Disconnect()
            end
            
            cleanAll()
            ESPLineActive = false
        end
        
        ESPLineCleanup = cleanup
        print("ESP LINE ATIVADO")
        return true
    end
end

local function ToggleESPBody()
    if ESPBodyActive then
        ESPBodyActive = false
        if ESPBodyCleanup then
            ESPBodyCleanup()
            ESPBodyCleanup = nil
        end
        print("ESP BODY DESATIVADO")
        return false
    else
        ESPBodyActive = true
        
        local Players = game:GetService("Players")
        local RunService = game:GetService("RunService")
        
        local LocalPlayer = Players.LocalPlayer
        
        local activeHighlights = {}
        local characterConnections = {}
        local isCleaning = false
        
        local function cleanAll()
            if isCleaning then return end
            isCleaning = true
            
            for character, highlight in pairs(activeHighlights) do
                if highlight and highlight.Parent then
                    highlight:Destroy()
                end
                if characterConnections[character] then
                    for _, conn in pairs(characterConnections[character]) do
                        pcall(function() conn:Disconnect() end)
                    end
                end
            end
            
            table.clear(activeHighlights)
            table.clear(characterConnections)
            
            isCleaning = false
        end
        
        local function createHighlight()
            local highlight = Instance.new("Highlight")
            highlight.Name = "V3ENO_Body"
            highlight.FillTransparency = 0.7
            highlight.OutlineTransparency = 0.3
            highlight.OutlineColor = Color3.new(1, 1, 1)
            highlight.DepthMode = Enum.HighlightDepthMode.AlwaysOnTop
            return highlight
        end
        
        local function getTeamColor(targetPlayer)
            if not targetPlayer or targetPlayer == LocalPlayer then return nil end
            
            local localTeam = LocalPlayer.Team
            local targetTeam = targetPlayer.Team
            
            if not localTeam or not targetTeam then
                return Color3.fromRGB(255, 255, 0)
            end
            
            if localTeam == targetTeam then
                return Color3.fromRGB(0, 150, 255)
            else
                return Color3.fromRGB(255, 0, 0)
            end
        end
        
        local function removeCharacter(character)
            if not character then return end
            
            if activeHighlights[character] then
                activeHighlights[character]:Destroy()
                activeHighlights[character] = nil
            end
            
            if characterConnections[character] then
                for _, conn in pairs(characterConnections[character]) do
                    pcall(function() conn:Disconnect() end)
                end
                characterConnections[character] = nil
            end
        end
        
        local function isValidCharacter(character)
            if not character or not character:IsA("Model") then return false end
            
            local player = Players:GetPlayerFromCharacter(character)
            if not player then return false end
            if player == LocalPlayer then return false end
            
            local humanoid = character:FindFirstChildOfClass("Humanoid")
            if not humanoid or humanoid.Health <= 0 then return false end
            
            return true
        end
        
        local function setupCharacter(character)
            if not isValidCharacter(character) then return end
            
            removeCharacter(character)
            
            local highlight = createHighlight()
            highlight.Adornee = character
            highlight.Parent = character
            activeHighlights[character] = highlight
            
            local player = Players:GetPlayerFromCharacter(character)
            local connections = {}
            
            local function updateColor()
                if not highlight or highlight.Parent ~= character then return end
                
                local currentPlayer = Players:GetPlayerFromCharacter(character)
                local color = getTeamColor(currentPlayer)
                if color then
                    highlight.FillColor = color
                else
                    removeCharacter(character)
                end
            end
            
            if player then
                table.insert(connections, player:GetPropertyChangedSignal("Team"):Connect(updateColor))
                table.insert(connections, LocalPlayer:GetPropertyChangedSignal("Team"):Connect(updateColor))
            end
            
            local humanoid = character:FindFirstChildOfClass("Humanoid")
            if humanoid then
                table.insert(connections, humanoid.Died:Connect(function()
                    removeCharacter(character)
                end))
                table.insert(connections, humanoid:GetPropertyChangedSignal("Health"):Connect(function()
                    if humanoid.Health <= 0 then
                        removeCharacter(character)
                    end
                end))
            end
            
            table.insert(connections, character.AncestryChanged:Connect(function()
                if not character or not character.Parent then
                    removeCharacter(character)
                end
            end))
            
            characterConnections[character] = connections
            updateColor()
        end
        
        local function checkExistingCharacters()
            for _, player in pairs(Players:GetPlayers()) do
                if player ~= LocalPlayer and player.Character then
                    setupCharacter(player.Character)
                end
            end
        end
        
        local function playerAdded(player)
            local charAddedConn = player.CharacterAdded:Connect(function(character)
                task.wait(1)
                if ESPBodyActive then
                    setupCharacter(character)
                end
            end)
            if player.Character and ESPBodyActive then
                task.spawn(setupCharacter, player.Character)
            end
            
            return charAddedConn
        end
        
        local playersConn = Players.PlayerAdded:Connect(playerAdded)
        local playerRemovedConn = Players.PlayerRemoving:Connect(function(player)
            if player.Character then
                removeCharacter(player.Character)
            end
        end)
        
        local playerCharAddedConn = LocalPlayer.CharacterAdded:Connect(function()
            task.wait(1)
            if ESPBodyActive then
                cleanAll()
                checkExistingCharacters()
            end
        end)
        
        local teamChangedConn = LocalPlayer:GetPropertyChangedSignal("Team"):Connect(function()
            if not ESPBodyActive then return end
            for character, highlight in pairs(activeHighlights) do
                if character and highlight and highlight.Parent then
                    local player = Players:GetPlayerFromCharacter(character)
                    local color = getTeamColor(player)
                    if color then
                        highlight.FillColor = color
                    end
                end
            end
        end)
        
        local heartbeatConn = RunService.Heartbeat:Connect(function()
            if not ESPBodyActive then return end
            for character, highlight in pairs(activeHighlights) do
                if not isValidCharacter(character) then
                    removeCharacter(character)
                end
            end
        end)
        
        checkExistingCharacters()
        
        local playerConnections = {}
        for _, player in pairs(Players:GetPlayers()) do
            if player ~= LocalPlayer then
                playerConnections[player] = playerAdded(player)
            end
        end
        
        local function cleanup()
            playersConn:Disconnect()
            playerRemovedConn:Disconnect()
            playerCharAddedConn:Disconnect()
            teamChangedConn:Disconnect()
            heartbeatConn:Disconnect()
            
            for _, conn in pairs(playerConnections) do
                conn:Disconnect()
            end
            
            cleanAll()
            ESPBodyActive = false
        end
        
        ESPBodyCleanup = cleanup
        print("ESP BODY ATIVADO")
        return true
    end
end

local function ToggleAimbot()
    if AimbotActive then
        AimbotActive = false
        return false
    else
        AimbotActive = true
        local success, scriptFunc = pcall(function()
            return loadstring(game:HttpGet("https://raw.githubusercontent.com/v3nenohub/SHARPSCRIPTS/refs/heads/main/SHARPAIMBOT"))()
        end)
        if success and scriptFunc then
            pcall(function()
                scriptFunc()
            end)
            return true
        else
            AimbotActive = false
            return false
        end
    end
end

local function ToggleSpeedHack()
    if SpeedHack.Active then
        if SpeedHack.Connection then SpeedHack.Connection:Disconnect() SpeedHack.Connection = nil end
        if LocalPlayer.Character then
            local humanoid = LocalPlayer.Character:FindFirstChildOfClass("Humanoid")
            if humanoid then humanoid.WalkSpeed = 16 end
        end
        SpeedHack.Active = false
        return false
    else
        SpeedHack.Connection = RunService.Heartbeat:Connect(function()
            if SpeedHack.Active and LocalPlayer.Character then
                local humanoid = LocalPlayer.Character:FindFirstChildOfClass("Humanoid")
                if humanoid then humanoid.WalkSpeed = SpeedHack.Speed end
            end
        end)
        SpeedHack.Active = true
        return true
    end
end

local function SetSpeedHackValue(value)
    SpeedHack.Speed = value
    if SpeedHack.Active and LocalPlayer.Character then
        local humanoid = LocalPlayer.Character:FindFirstChildOfClass("Humanoid")
        if humanoid then humanoid.WalkSpeed = value end
    end
end

local function ToggleFastSwitch()
    if FastSwitch.Active then
        if FastSwitch.Connection then FastSwitch.Connection:Disconnect() FastSwitch.Connection = nil end
        FastSwitch.Active = false
        return false
    else
        local mouse = game.Players.LocalPlayer:GetMouse()
        FastSwitch.Connection = mouse.Button1Down:Connect(function()
            if FastSwitch.Active then
                task.wait(0.02)
                VirtualInputManager:SendKeyEvent(true, Enum.KeyCode.Q, false, nil)
                task.wait(0.05)
                VirtualInputManager:SendKeyEvent(false, Enum.KeyCode.Q, false, nil)
            end
        end)
        FastSwitch.Active = true
        return true
    end
end

