    Layout.Padding = UDim.new(0, 6)
    Layout.SortOrder = Enum.SortOrder.LayoutOrder
    Layout.Parent = Container

    local debounce = false
    ToggleIcon.MouseButton1Click:Connect(function()
        if debounce then return end
        debounce = true
        local isOpening = not Main.Visible
        if isOpening then Main.Visible = true end
        local targetSize = isOpening and MainSize or UDim2.new(0, MainSize.X.Offset, 0, 0)
        local targetRot = isOpening and 0 or 180
        TweenService:Create(ToggleIcon, BackInfo, {Rotation = targetRot}):Play()
        local t = TweenService:Create(Main, SmoothInfo, {Size = targetSize})
        t:Play()
        t.Completed:Connect(function()
            if not isOpening then Main.Visible = false end
            debounce = false
        end)
    end)

    CloseBtn.MouseButton1Click:Connect(function()
        local t1 = TweenService:Create(Main, FastInfo, {Size = UDim2.new(0,0,0,0), BackgroundTransparency = 1})
        local t2 = TweenService:Create(ToggleIcon, FastInfo, {Size = UDim2.new(0,0,0,0)})
        t1:Play()
        t2:Play()
        task.wait(0.2)
        V3NENO_GUI:Destroy()
    end)

    Library:AddToggle(Container, "ESP NAME", function(v) 
