    end)
    
    Library:AddSlider(Container, "WALKSPEED CONFIG", 16, 35, function(v) 
        SetSpeedHackValue(v)
        print("WALKSPEED CONFIG:", v)
    end)
    
    Library:AddToggle(Container, "AIMBOT (Right Click)", function(v) 
        local status = ToggleAimbot()
        print("AIMBOT:", status and "ATIVADO" or "DESATIVADO")
    end)
    
    Library:AddToggle(Container, "AIMBOT MOBILE [COMING SOON]", function(v) 
        print("AIMBOT MOBILE: Em breve...")
        return false
    end)
    
    Library:AddToggle(Container, "SWITCH GUN / KNIFE", function(v) 
        local status = ToggleFastSwitch()
        print("SWITCH GUN/KNIFE:", status and "ATIVADO" or "DESATIVADO")
    end)
    
    local DiscordBtn = Instance.new("TextButton")
    DiscordBtn.Name = "DiscordBtn"
    DiscordBtn.Parent = Container
    DiscordBtn.Size = UDim2.new(1, 0, 0, 32)
    DiscordBtn.BackgroundColor3 = Color3.fromRGB(0, 100, 255)
    DiscordBtn.Text = "DISCORD"
    DiscordBtn.TextColor3 = Colors.Text
    DiscordBtn.Font = Enum.Font.GothamBold
    DiscordBtn.TextSize = 12
    DiscordBtn.ZIndex = 20
    DiscordBtn.AutoButtonColor = true
    Instance.new("UICorner", DiscordBtn).CornerRadius = UDim.new(0, 6)
    
    DiscordBtn.MouseButton1Click:Connect(function()
        if setclipboard then
            setclipboard("https://discord.gg/3JSw8fDQbu")
            DiscordBtn.Text = "COPIED"
            task.wait(1.5)
            DiscordBtn.Text = "DISCORD"
        else
            DiscordBtn.Text = "NO CLIPBOARD"
            task.wait(1.5)
            DiscordBtn.Text = "DISCORD"
        end
    end)

    return Container, V3NENO_GUI
end

function Library:AddToggle(parent, text, callback)
    local TFrame = Instance.new("TextButton")
    TFrame.Name = text .. "_Toggle"
    TFrame.Parent = parent
    TFrame.Size = UDim2.new(1, 0, 0, 36)
    TFrame.BackgroundColor3 = Colors.Secondary
    TFrame.Text = "  " .. text
    TFrame.Font = Enum.Font.GothamBold
    TFrame.TextColor3 = Colors.Text
    TFrame.TextSize = 12
    TFrame.TextXAlignment = Enum.TextXAlignment.Left
    TFrame.AutoButtonColor = true
    TFrame.ZIndex = 15
    
    local TCorner = Instance.new("UICorner")
    TCorner.CornerRadius = UDim.new(0, 6)
    TCorner.Parent = TFrame
    
    local Indicator = Instance.new("Frame")
    Indicator.Name = "Indicator"
    Indicator.Size = UDim2.new(0, 12, 0, 12)
    Indicator.Position = UDim2.new(1, -22, 0.5, -6)
    
    if text == "AIMBOT MOBILE [COMING SOON]" then
        Indicator.BackgroundColor3 = Colors.Danger
    else
        Indicator.BackgroundColor3 = Colors.Danger
    end
    
    Indicator.ZIndex = 16
    Indicator.Parent = TFrame
    
    local ICorner = Instance.new("UICorner")
    ICorner.CornerRadius = UDim.new(1, 0)
    ICorner.Parent = Indicator
    
    local active = false
    
    TFrame.MouseButton1Click:Connect(function()
        if text == "AIMBOT MOBILE [COMING SOON]" then
            return
        end
        
        active = not active
        TweenService:Create(Indicator, IndicatorInfo, {BackgroundColor3 = active and Colors.Accent or Colors.Danger}):Play()
        pcall(function() callback(active) end)
    end)
    
    if text == "AIMBOT MOBILE [COMING SOON]" then
        TFrame.MouseEnter:Connect(function()
            TweenService:Create(TFrame, FastInfo, {
                BackgroundColor3 = Color3.fromRGB(35, 35, 35)
            }):Play()
        end)
        
        TFrame.MouseLeave:Connect(function()
            TweenService:Create(TFrame, FastInfo, {
                BackgroundColor3 = Colors.Secondary
            }):Play()
        end)
    end
end

function Library:AddSlider(parent, text, min, max, callback)
    local SFrame = Instance.new("Frame")
    SFrame.Name = text .. "_Slider"
    SFrame.Size = UDim2.new(1, 0, 0, 60)
    SFrame.BackgroundColor3 = Colors.Secondary
    SFrame.ZIndex = 15
    SFrame.Parent = parent
    local SCorner = Instance.new("UICorner")
    SCorner.CornerRadius = UDim.new(0, 6)
    SCorner.Parent = SFrame
    local Label = Instance.new("TextLabel")
    Label.Text = "  " .. text
    Label.Size = UDim2.new(1, 0, 0, 28)
    Label.TextColor3 = Colors.Text
    Label.Font = Enum.Font.GothamBold
    Label.TextSize = 12
    Label.BackgroundTransparency = 1
    Label.TextXAlignment = Enum.TextXAlignment.Left
    Label.ZIndex = 16
    Label.Parent = SFrame
    local ValText = Instance.new("TextLabel")
    ValText.Text = tostring(min)
    ValText.Size = UDim2.new(0, 40, 0, 28)
    ValText.Position = UDim2.new(1, -42, 0, 0)
    ValText.TextColor3 = Colors.Accent
    ValText.Font = Enum.Font.GothamBold
    ValText.BackgroundTransparency = 1
    ValText.ZIndex = 16
    ValText.Parent = SFrame
    local Bar = Instance.new("TextButton")
    Bar.Size = UDim2.new(0.9, 0, 0, 4)
    Bar.Position = UDim2.new(0.05, 0, 0.75, 0)
    Bar.BackgroundColor3 = Color3.fromRGB(25, 25, 25)
    Bar.Text = ""
    Bar.AutoButtonColor = false
    Bar.ZIndex = 16
    Bar.Parent = SFrame
    Instance.new("UICorner", Bar)
    local Fill = Instance.new("Frame")
    Fill.Size = UDim2.new(0, 0, 1, 0)
    Fill.BackgroundColor3 = Colors.Accent
    Fill.ZIndex = 17
    Fill.Parent = Bar
    Instance.new("UICorner", Fill)
    local function Update(input)
        local ratio = math.clamp((input.Position.X - Bar.AbsolutePosition.X) / Bar.AbsoluteSize.X, 0, 1)
        local v = math.floor(min + (max - min) * ratio)
        TweenService:Create(Fill, FastInfo, {Size = UDim2.new(ratio, 0, 1, 0)}):Play()
        ValText.Text = tostring(v)
        callback(v)
    end
    Bar.InputBegan:Connect(function(input)
        if input.UserInputType == Enum.UserInputType.MouseButton1 or input.UserInputType == Enum.UserInputType.Touch then
            local move = UserInputService.InputChanged:Connect(function(i)
                if i.UserInputType == Enum.UserInputType.MouseMovement or i.UserInputType == Enum.UserInputType.Touch then 
                    Update(i) 
                end
            end)
            input.Changed:Connect(function() 
                if input.UserInputState == Enum.UserInputState.End then 
                    move:Disconnect() 
                end 
            end)
        end
    end)
end

LoadPersistentData()
JunkieAPI = InitializeJunkie()

if not PersistentData.verifiedKey then
    Library:CreateKeyPanel()
else
    local success, err = pcall(function()
        local isValid, _ = ValidateKey(PersistentData.verifiedKey)
        
        if isValid then
            Library:CreateWindow()
        else
            PersistentData.verifiedKey = nil
            SavePersistentData()
            Library:CreateKeyPanel()
        end
    end)
    
    if not success then
        PersistentData.verifiedKey = nil
        SavePersistentData()
        Library:CreateKeyPanel()
    end
end

